import java.util.Scanner;

public class COVID {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int n = sc.nextInt();
        long k = sc.nextLong();

        final int MOD = 998244353;
        if (k > n - 1) {
            System.out.println(0);
            return;
        }

        int[] factorials = new int[n + 1];
        factorials[0] = 1;
        for (int i = 1; i <= n; i++) {
            factorials[i] = (int) ((long) factorials[i - 1] * i % MOD);
        }

        int remaining = n - (int) k;
        long total = 0;

        for (int i = 0; i <= remaining; i++) {
            long comb = nCr(remaining, i, factorials, MOD);
            long power = powMod(remaining - i, n, MOD);
            long term = (comb * power) % MOD;
            if (i % 2 == 1) {
                term = -term;
            }
            total = (total + term + MOD) % MOD;
        }

        total = (total * nCr(n, remaining, factorials, MOD)) % MOD;
        if (k != 0) {
            total = (total * 2) % MOD;
        }
        System.out.println(total);
    }

    static long powMod(long base, long exp, int mod) {
        long res = 1;
        base %= mod;
        while (exp > 0) {
            if ((exp & 1) == 1) res = (res * base) % mod;
            base = (base * base) % mod;
            exp >>= 1;
        }
        return res;
    }

    static long nCr(int n, int r, int[] fac, int mod) {
        long numerator = fac[n];
        long denom = ((long) fac[r] * fac[n - r]) % mod;
        return numerator * powMod(denom, mod - 2, mod) % mod;
    }
}
